#!/usr/bin/env node
import http from 'node:http';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import readline from 'node:readline';
const VER='1.0.0',PROTOS=['2025-11-25','2025-06-18','2025-03-26','2024-11-05'],GUID='258EAFA5-E914-47DA-95CA-C5AB0DC85B11',MAXMSG=64*2**20,FRAG=2**20;
const BASE=+(process.env.AMNICAD_PORT||41777),SPAN=+(process.env.AMNICAD_PORT_SPAN||5),CWD=process.cwd(),SITE='https://amni-scient.com/cad/';
const ORIGINS=new Set(['https://amni-scient.com','https://www.amni-scient.com',...[0,1,2,3,4].flatMap(i=>['http://127.0.0.1:'+(41790+i),'http://localhost:'+(41790+i)]),...(process.env.AMNICAD_ORIGINS||'').split(',').map(s=>s.trim().replace(/\/$/,'')).filter(Boolean)]);
const CFG=process.env.AMNICAD_CONFIG||(process.platform==='win32'?path.join(process.env.APPDATA||path.join(os.homedir(),'AppData','Roaming'),'amnicad'):path.join(process.env.XDG_CONFIG_HOME||path.join(os.homedir(),'.config'),'amnicad')),TOKF=path.join(CFG,'bridge-tokens.json');
const log=(...a)=>process.stderr.write('[amnicad-mcp] '+a.join(' ')+'\n');
const okOrigin=o=>!!o&&(ORIGINS.has(o)||/^http:\/\/(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/.test(o));
const okHost=h=>/^(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/.test(h||'');
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const newCode=()=>String(crypto.randomInt(0,1e6)).padStart(6,'0');
const readToks=()=>{try{return JSON.parse(fs.readFileSync(TOKF,'utf8')).tokens||[];}catch{return[];}};
const saveTok=(tok,origin)=>{try{fs.mkdirSync(CFG,{recursive:true,mode:0o700});const t=[...readToks().filter(x=>x.h!==sha(tok)),{h:sha(tok),origin,t:Date.now()}].slice(-20);fs.writeFileSync(TOKF,JSON.stringify({tokens:t}),{mode:0o600});}catch(e){log('could not save token:',e.message);}};
const tokOK=(tok,origin)=>typeof tok==='string'&&tok.length>=32&&readToks().some(x=>x.h===sha(tok)&&x.origin===origin);
let code=newCode(),fails=0,lockUntil=0,page=null,port=0,client={name:'MCP client'},seq=0;
const pend=new Map();
function frame(op,buf,fin=true){const n=buf.length,h=n<126?Buffer.from([(fin?0x80:0)|op,n]):n<65536?Buffer.from([(fin?0x80:0)|op,126,n>>8,n&255]):Buffer.alloc(10);if(n>=65536){h[0]=(fin?0x80:0)|op;h[1]=127;h.writeBigUInt64BE(BigInt(n),2);}return Buffer.concat([h,buf]);}
function wsSend(c,obj){if(c.dead)return;const b=Buffer.from(typeof obj==='string'?obj:JSON.stringify(obj));if(b.length<=FRAG)return c.sock.write(frame(1,b));for(let i=0;i<b.length;i+=FRAG)c.sock.write(frame(i?0:1,b.subarray(i,i+FRAG),i+FRAG>=b.length));}
function wsClose(c,codeN=1000,why=''){if(c.dead)return;const r=Buffer.from(why).subarray(0,120),b=Buffer.alloc(2+r.length);b.writeUInt16BE(codeN,0);r.copy(b,2);try{c.sock.write(frame(8,b));c.sock.end();}catch{}c.dead=true;clearInterval(c.ping);setTimeout(()=>c.sock.destroy(),500).unref();}
function wsData(c,d){c.buf=c.buf.length?Buffer.concat([c.buf,d]):d;while(c.buf.length>=2){const b0=c.buf[0],b1=c.buf[1],fin=b0&0x80,op=b0&15,masked=b1&0x80;let n=b1&127,o=2;if(n===126){if(c.buf.length<4)return;n=c.buf.readUInt16BE(2);o=4;}else if(n===127){if(c.buf.length<10)return;const big=c.buf.readBigUInt64BE(2);if(big>BigInt(MAXMSG))return wsClose(c,1009,'too big');n=Number(big);o=10;}if(!masked)return wsClose(c,1002,'unmasked');if(c.buf.length<o+4+n)return;const mask=c.buf.subarray(o,o+4),p=Buffer.from(c.buf.subarray(o+4,o+4+n));for(let i=0;i<n;i++)p[i]^=mask[i&3];c.buf=c.buf.subarray(o+4+n);if(op===8){wsClose(c,1000);continue;}if(op===9){c.sock.write(frame(10,p));continue;}if(op===10)continue;if(op===1||op===2){c.parts=[p];c.size=n;}else if(op===0&&c.parts)c.parts.push(p),c.size+=n;else return wsClose(c,1002,'bad frame');if(c.size>MAXMSG)return wsClose(c,1009,'too big');if(fin){const msg=Buffer.concat(c.parts).toString('utf8');c.parts=null;try{onPage(c,JSON.parse(msg));}catch(e){log('bad page message:',e.message);}}}}
function welcome(c,tok){if(page&&page!==c){wsSend(page,{t:'bye',reason:'Another Amni-CAD tab connected to this assistant.'});wsClose(page,4000,'replaced');}page=c;c.auth=true;wsSend(c,{t:'welcome',token:tok,client,server:{name:'amnicad-mcp',version:VER,port}});log('page connected from',c.origin);}
function onPage(c,m){if(!c.auth){if(m.t!=='hello'&&m.t!=='pair')return;if(m.token&&tokOK(m.token,c.origin))return welcome(c,m.token);if(m.code!=null&&m.code!==''){if(Date.now()<lockUntil)return wsSend(c,{t:'need-code',reason:'Too many wrong codes. Wait a minute, then ask the assistant for the new pairing code.'});if(String(m.code).replace(/\D/g,'')===code){const tok=crypto.randomBytes(32).toString('base64url');saveTok(tok,c.origin);code=newCode();fails=0;return welcome(c,tok);}if(++fails>=5){fails=0;lockUntil=Date.now()+60000;code=newCode();log('too many wrong pairing codes; new code issued');}return wsSend(c,{t:'need-code',reason:'That code did not match.'});}return wsSend(c,{t:'need-code',reason:m.token?'This browser is not paired with this computer yet.':'Enter the pairing code your assistant shows.'});}
  if(m.t==='res'&&pend.has(m.id)){const p=pend.get(m.id);pend.delete(m.id);clearTimeout(p.tm);m.ok?p.res(m.result):p.rej(new Error(m.error||'page error'));}}
function onClose(c){c.dead=true;clearInterval(c.ping);if(page===c){page=null;log('page disconnected');for(const[id,p]of pend)if(p.c===c){pend.delete(id);clearTimeout(p.tm);p.rej(new Error('The Amni-CAD page disconnected (tab closed or reloaded). Ask the user to reopen it; the bridge reconnects automatically.'));}}}
const srv=http.createServer((q,r)=>{r.writeHead(426,{'Content-Type':'text/plain'});r.end('Amni-CAD local bridge. Open '+SITE+' → AI tab → Local bridge.\n');});
srv.on('upgrade',(q,sock)=>{const key=q.headers['sec-websocket-key'],origin=q.headers.origin,deny=(s,t)=>{log('rejected connection:',t,origin||'(no origin)');sock.end('HTTP/1.1 '+s+'\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\n'+t);};if(!okHost(q.headers.host))return deny('421 Misdirected Request','bad host');if(!okOrigin(origin))return deny('403 Forbidden','origin not allowed');if(!key||String(q.headers.upgrade).toLowerCase()!=='websocket'||q.headers['sec-websocket-version']!=='13')return deny('400 Bad Request','not a websocket');sock.setNoDelay(true);sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+crypto.createHash('sha1').update(key+GUID).digest('base64')+'\r\n\r\n');const c={sock,origin,buf:Buffer.alloc(0),parts:null,size:0,auth:false};c.ping=setInterval(()=>!c.dead&&sock.write(frame(9,Buffer.alloc(0))),20000);c.ping.unref();setTimeout(()=>!c.auth&&wsClose(c,4001,'pairing timeout'),600000).unref();sock.on('data',d=>wsData(c,d));sock.on('close',()=>onClose(c));sock.on('error',()=>onClose(c));});
function listen(p){return new Promise((ok,no)=>{const e=err=>{srv.off('listening',l);no(err);},l=()=>{srv.off('error',e);ok(p);};srv.once('error',e);srv.once('listening',l);srv.listen(p,'127.0.0.1');});}
const ready=(async()=>{for(let p=BASE;p<BASE+SPAN;p++){try{port=await listen(p);log('bridge listening on ws://127.0.0.1:'+port,'· pairing code',code);return port;}catch(e){if(e.code!=='EADDRINUSE')throw e;}}log('all bridge ports',BASE+'-'+(BASE+SPAN-1),'are busy; close other assistant sessions using Amni-CAD');port=0;return 0;})();
const howTo=()=>'Ask the user to open '+SITE+' in a desktop browser, choose the AI tab → Local bridge → Connect'+(port?'':' (no free bridge port: close other assistant sessions that use Amni-CAD, then restart this MCP server)')+'. If the page asks for a pairing code, tell them to type '+code+'. Pairing is remembered in that browser.';
async function needPage(){for(let i=0;i<30&&!page;i++)await new Promise(r=>setTimeout(r,100));if(!page){const e=new Error('No Amni-CAD page is connected. '+howTo());e.user=true;throw e;}return page;}
async function callPage(method,params={},ms=120000){const c=await needPage(),id=++seq;return new Promise((res,rej)=>{const tm=setTimeout(()=>{pend.delete(id);rej(new Error(method+' timed out after '+Math.round(ms/1000)+' s. The page may be busy or the tab is in the background; check the Amni-CAD tab.'));},ms);pend.set(id,{res,rej,tm,c});wsSend(c,{t:'req',id,method,params});});}
const SEL={description:'Face selector, same as the design language: {"side":"+Z"} (outermost faces on that side of the bounding box), {"normal":"-X"} (every face with that normal), {"type":"CYLINDER"}, or {"by":"pick","pts":[[x,y,z],...]} (faces nearest these points, in document units). A sketch "face" also takes "top"/"bottom"/"front"/"back"/"right"/"left", a face id from get_state.faces, or {"normal":[nx,ny,nz],"at":[x,y,z]}, a stable reference that follows the face when the part changes. A list of selectors is also accepted.',anyOf:[{type:'object'},{type:'array',items:{type:'object'}}]};
